/* ===== Orchard — Premium Tech E-Commerce Styles ===== */

/* Reset & Base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f7;
  --bg-tertiary: #fafafa;
  --text-primary: #1d1d1f;
  --text-secondary: #6e6e73;
  --text-tertiary: #86868b;
  --accent: #0066cc;
  --accent-hover: #0055aa;
  --border: #d2d2d7;
  --border-light: #e8e8ed;
  --badge-new: #bf4800;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --transition-fast: 0.15s ease;
  --transition: 0.3s ease;
  --max-width: 1200px;
  --nav-height: 48px;
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  color: var(--text-primary);
  background: var(--bg-primary);
  line-height: 1.5;
  font-size: 16px;
  overflow-x: hidden;
}

img { display: block; max-width: 100%; }
a { color: var(--accent); text-decoration: none; }
a:hover { color: var(--accent-hover); }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }

/* ===== Navigation ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
  height: var(--nav-height);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 22px;
  height: 100%;
}

.nav-brand {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.3px;
}

.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
  font-size: 13px;
  font-weight: 400;
  letter-spacing: -0.1px;
}

.nav-links a {
  color: var(--text-primary);
  opacity: 0.85;
  transition: opacity var(--transition-fast);
}

.nav-links a:hover { opacity: 1; color: var(--text-primary); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 13px;
}

.nav-actions svg { width: 18px; height: 18px; opacity: 0.8; }

/* ===== Ribbon Banner ===== */
.ribbon {
  background: var(--text-primary);
  color: var(--bg-primary);
  text-align: center;
  padding: 10px 22px;
  font-size: 13px;
  letter-spacing: -0.1px;
}

.ribbon a { color: #6bb5ff; margin-left: 4px; }
.ribbon a:hover { color: #8cc8ff; text-decoration: underline; }

/* ===== Hero Sections ===== */
.hero {
  text-align: center;
  padding: 60px 22px 40px;
  background: var(--bg-primary);
}

.hero h1 {
  font-size: clamp(40px, 6vw, 56px);
  font-weight: 600;
  letter-spacing: -1px;
  line-height: 1.1;
  margin-bottom: 12px;
}

.hero-subtitle {
  font-size: clamp(17px, 2.5vw, 21px);
  color: var(--text-secondary);
  font-weight: 400;
  letter-spacing: -0.2px;
  margin-bottom: 24px;
}

.hero-ctas {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.2px;
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-hover); color: #fff; }

.btn-outline {
  border: 1px solid var(--border);
  color: var(--accent);
  background: transparent;
}
.btn-outline:hover { background: rgba(0,102,204,0.05); }

.btn-link {
  color: var(--accent);
  padding: 0;
  font-size: 15px;
  font-weight: 500;
}
.btn-link:hover { text-decoration: underline; }

/* ===== Section Headers ===== */
.section-header {
  text-align: center;
  padding: 48px 22px 32px;
}

.section-header h2 {
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 600;
  letter-spacing: -0.6px;
  margin-bottom: 6px;
}

.section-header .subtitle {
  font-size: 17px;
  color: var(--text-secondary);
  font-weight: 400;
}

/* ===== Carousels ===== */
.carousel-container {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.carousel-wrapper {
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
}

.carousel-wrapper::-webkit-scrollbar { display: none; }

.carousel-track {
  display: flex;
  gap: 20px;
  padding: 0 22px 20px;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
  opacity: 0.85;
}

.carousel-arrow:hover { opacity: 1; box-shadow: var(--shadow-lg); transform: translateY(-50%) scale(1.05); }
.carousel-arrow:active { transform: translateY(-50%) scale(0.95); }

.carousel-arrow.prev { left: 4px; }
.carousel-arrow.next { right: 4px; }

.carousel-arrow svg { width: 20px; height: 20px; }

/* ===== Product Cards (carousel style) ===== */
.product-card {
  scroll-snap-align: start;
  flex: 0 0 260px;
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.product-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.product-card-image {
  width: 100%;
  height: 260px;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  overflow: hidden;
}

.product-card-image .placeholder {
  width: 160px;
  height: 160px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 50%, #e0e0e6 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  color: var(--text-tertiary);
  text-align: center;
  padding: 16px;
}

.product-card-body { padding: 16px; }

.product-card-body .badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  color: var(--badge-new);
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.product-card-body h3 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.3px;
  margin-bottom: 4px;
}

.product-card-body .tagline {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 10px;
  line-height: 1.35;
}

.product-card-body .price {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 2px;
}

.product-card-body .monthly {
  font-size: 13px;
  color: var(--text-secondary);
}

/* ===== Product Icon Bar ===== */
.icon-bar {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.icon-bar-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 4px 22px 16px;
  justify-content: center;
}

.icon-bar-track::-webkit-scrollbar { display: none; }

.icon-bar-item {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  cursor: pointer;
  min-width: 72px;
}

.icon-bar-item:hover { background: var(--bg-secondary); }

.icon-bar-item .icon-circle {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

.icon-bar-item span {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
}

/* ===== Product Grid (Homepage Tiles) ===== */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  padding: 0 22px 40px;
}

.product-tile {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  min-height: 520px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  padding: 48px 32px;
  text-align: center;
}

.product-tile .tile-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.product-tile .tile-content {
  position: relative;
  z-index: 1;
  margin-bottom: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.product-tile h3 {
  font-size: 32px;
  font-weight: 600;
  letter-spacing: -0.5px;
  margin-bottom: 6px;
}

.product-tile .tile-tagline {
  font-size: 16px;
  color: var(--text-primary);
  opacity: 0.8;
  margin-bottom: 16px;
  max-width: 320px;
}

.product-tile .tile-ctas {
  display: flex;
  gap: 24px;
  align-items: center;
}

.product-tile .product-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.product-tile .product-visual .vis-placeholder {
  width: 280px;
  height: 280px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text-tertiary);
}

/* Tile color variants */
.tile-light { background: #f5f5f7; color: var(--text-primary); }
.tile-dark { background: #1d1d1f; color: #f5f5f7; }
.tile-dark .tile-tagline { color: #a1a1a6; }
.tile-warm { background: linear-gradient(135deg, #faf7f2 0%, #f5efe4 100%); color: var(--text-primary); }
.tile-cool { background: linear-gradient(135deg, #f2f5f8 0%, #e8eef3 100%); color: var(--text-primary); }
.tile-gradient1 { background: linear-gradient(135deg, #f8f4fa 0%, #ede4f2 100%); color: var(--text-primary); }
.tile-gradient2 { background: linear-gradient(135deg, #f2f7f4 0%, #e2ede5 100%); color: var(--text-primary); }
.tile-dark .btn-outline { border-color: rgba(255,255,255,0.3); color: #6bb5ff; }
.tile-dark .btn-outline:hover { background: rgba(255,255,255,0.1); }

/* ===== Entertainment Tabs ===== */
.entertainment {
  background: var(--bg-secondary);
  padding: 0 22px 48px;
}

.tabs-nav {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-bottom: 28px;
  padding-top: 12px;
}

.tab-btn {
  padding: 8px 20px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.tab-btn:hover { color: var(--text-primary); background: rgba(0,0,0,0.04); }
.tab-btn.active { background: var(--text-primary); color: #fff; }

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.entertainment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.ent-card {
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.ent-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.ent-card-image {
  height: 200px;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  color: var(--text-tertiary);
}

.ent-card-body { padding: 14px 16px; }

.ent-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.ent-card-body p {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 10px;
}

/* ===== Help / Support Cards ===== */
.cards-grid {
  display: flex;
  gap: 20px;
  padding: 0 22px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.support-card {
  flex: 0 0 280px;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  text-align: center;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.support-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.support-card .card-icon {
  font-size: 40px;
  margin-bottom: 16px;
}

.support-card h4 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.45;
}

/* ===== Savings / Offer Cards ===== */
.savings-grid {
  display: flex;
  gap: 20px;
  padding: 0 22px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  overflow-x: auto;
  scrollbar-width: none;
}

.savings-grid::-webkit-scrollbar { display: none; }

.savings-card {
  flex: 0 0 220px;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: transform var(--transition-fast);
  text-align: center;
}

.savings-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.savings-card .card-icon { font-size: 32px; margin-bottom: 12px; }

.savings-card h4 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }

.savings-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.4; }

/* ===== Brand Collab ===== */
.brand-collab {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 22px;
  text-align: center;
}

.brand-collab-banner {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: var(--radius-xl);
  padding: 48px;
  color: #fff;
  position: relative;
  overflow: hidden;
}

.brand-collab-banner h3 {
  font-size: 28px;
  font-weight: 600;
  margin-bottom: 8px;
}

.brand-collab-banner p {
  font-size: 17px;
  color: rgba(255,255,255,0.8);
  margin-bottom: 20px;
}

/* ===== Quick Links ===== */
.quick-links {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 20px 22px 40px;
}

.quick-links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.quick-link {
  flex: 0 0 auto;
  padding: 10px 18px;
  background: var(--bg-secondary);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  color: var(--accent);
  transition: all var(--transition-fast);
}

.quick-link:hover { background: #e8e8ed; color: var(--accent-hover); }

/* ===== Category Hero (Laptops/Tablets) ===== */
.cat-hero {
  text-align: center;
  padding: 48px 22px 32px;
  background: var(--bg-secondary);
}

.cat-hero h1 {
  font-size: clamp(36px, 5vw, 48px);
  font-weight: 600;
  letter-spacing: -0.8px;
  margin-bottom: 8px;
}

.cat-hero p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 500px;
  margin: 0 auto;
}

/* ===== Sticky Section Nav ===== */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 999;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: 4px;
  padding: 0 22px;
  overflow-x: auto;
  scrollbar-width: none;
}

.section-nav-inner::-webkit-scrollbar { display: none; }

.section-nav-item {
  flex: 0 0 auto;
  padding: 14px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.section-nav-item:hover { color: var(--text-primary); }
.section-nav-item.active { color: var(--text-primary); border-bottom-color: var(--text-primary); }

/* ===== Page Section Spacing ===== */
.page-section {
  scroll-margin-top: calc(var(--nav-height) + 44px);
  padding: 40px 0;
}

/* ===== Guide Cards ===== */
.guides-grid {
  display: flex;
  gap: 20px;
  padding: 0 22px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  overflow-x: auto;
  scrollbar-width: none;
}

.guides-grid::-webkit-scrollbar { display: none; }

.guide-card {
  flex: 0 0 280px;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  text-align: center;
  transition: transform var(--transition-fast);
}

.guide-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.guide-card .card-icon { font-size: 36px; margin-bottom: 12px; }

.guide-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 6px; }

.guide-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.4; }

/* ===== Setup Support ===== */
.setup-support {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 22px;
  text-align: center;
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
}

/* ===== Experience Section ===== */
.experience-section {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 22px;
}

/* ===== Special Stores ===== */
.special-stores-grid {
  display: flex;
  gap: 20px;
  padding: 0 22px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  overflow-x: auto;
  scrollbar-width: none;
}

.special-stores-grid::-webkit-scrollbar { display: none; }

.special-store-card {
  flex: 0 0 200px;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  transition: transform var(--transition-fast);
}

.special-store-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.special-store-card .card-icon { font-size: 32px; margin-bottom: 12px; }

.special-store-card h4 { font-size: 15px; font-weight: 600; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-secondary);
  padding: 40px 22px 24px;
  margin-top: 40px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  font-size: 12px;
  color: var(--text-tertiary);
  line-height: 1.6;
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-light);
}

.footer-legal p + p { margin-top: 8px; }

.footer-nav {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 24px;
}

.footer-col h5 {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 10px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li { margin-bottom: 6px; }

.footer-col a {
  font-size: 12px;
  color: var(--text-tertiary);
  transition: color var(--transition-fast);
}

.footer-col a:hover { color: var(--text-primary); text-decoration: underline; }

.footer-bottom {
  padding-top: 20px;
  border-top: 1px solid var(--border-light);
  font-size: 12px;
  color: var(--text-tertiary);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  .entertainment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-nav { grid-template-columns: repeat(3, 1fr); }
  .product-tile { min-height: 400px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .product-grid { grid-template-columns: 1fr; }
  .entertainment-grid { grid-template-columns: 1fr; }
  .footer-nav { grid-template-columns: 1fr; }
  .product-tile { min-height: 360px; }
  .hero { padding: 40px 16px 32px; }
  .hero h1 { font-size: 36px; }
  .cards-grid { flex-direction: column; }
  .support-card { flex: 0 0 auto; }
  .brand-collab-banner { padding: 32px 24px; }
  .icon-bar-track { justify-content: flex-start; }
  .tabs-nav { flex-wrap: wrap; }

  /* Footer accordion on mobile */
  .footer-nav {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
